import { clamp } from './metrics';
import type { Step, Terrain } from './types';

export function syntheticStep(time: Date, terrain: Terrain, decline = 1, random = Math.random): Step {
  const hour = time.getHours();
  const fatigue = hour >= 18 ? 5 : hour >= 12 ? 2.5 : 0;
  const noise = (random() - 0.5) * 3;
  return {
    time: time.toISOString(), terrain,
    minClearanceMm: Math.max(2, 26 - decline * 6 - fatigue - (terrain === 'level' ? 0 : 2) + noise),
    peakDorsiDeg: 13 - decline * 4 - fatigue * 0.45 + noise * 0.3,
    strideMs: Math.round(1040 + decline * 60 + (random() - 0.5) * (70 + decline * 170 + fatigue * 25)),
    assistPct: Math.round(clamp(25 + decline * 25 + fatigue * 3 + (terrain === 'level' ? 0 : 8), 0, 100)),
  };
}
export const clamp = (value: number, min = 0, max = 1) => Math.min(max, Math.max(min, value));

export function stabilityScore(input: {
  clearance: number; dorsi: number; baselineDorsi: number; strideMean: number;
  strideStddev: number; stairSteps: number; stairNearTrips: number; assist: number;
}) {
  const clearance = clamp(input.clearance / 20);
  const dorsi = clamp(input.dorsi / Math.max(1, input.baselineDorsi));
  const rhythm = clamp(1 - input.strideStddev / Math.max(1, input.strideMean) / 0.3);
  const stairs = clamp(1 - input.stairNearTrips * 100 / Math.max(1, input.stairSteps) / 5);
  const assist = 1 - clamp(input.assist / 100);
  return Math.round(100 * (0.35 * clearance + 0.2 * dorsi + 0.2 * rhythm + 0.15 * stairs + 0.1 * assist));
}
