import { readdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const dir = process.argv[2] ?? '../data/gait-in-neurodegenerative-disease-database-1.0.0';

async function rightStrides(file: string) {
  const text = await readFile(join(dir, file), 'utf8');
  return text.trim().split('\n')
    .map(line => Math.round(Number(line.trim().split(/\s+/)[2]) * 1000))
    .filter(ms => ms >= 600 && ms <= 2500);
}

const cv = (xs: number[]) => {
  const mean = xs.reduce((a, b) => a + b, 0) / xs.length;
  return Math.sqrt(xs.reduce((a, b) => a + (b - mean) ** 2, 0) / xs.length) / mean;
};
const median = (xs: number[]) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)];

async function main() {
  const files = (await readdir(dir)).filter(f => f.endsWith('.ts'));
  const group = async (prefix: string) => Promise.all(files.filter(f => new RegExp(`^${prefix}\\d+\\.ts$`).test(f)).map(rightStrides));
  const [als, control] = await Promise.all([group('als'), group('control')]);
  const out = {
    source: 'PhysioNet Gait in Neurodegenerative Disease Database v1.0.0 (Hausdorff et al.), right-foot stride intervals',
    alsStrideCv: median(als.map(cv)),
    controlStrideCv: median(control.map(cv)),
    als,
  };
  await writeFile(new URL('../data/physionet-strides.json', import.meta.url), JSON.stringify(out));
  console.log({ alsSubjects: als.length, controlSubjects: control.length, alsStrideCv: out.alsStrideCv, controlStrideCv: out.controlStrideCv, strides: als.flat().length });
}
void main();

import physionet from '../data/physionet-strides.json';
import { clamp } from './metrics';
import type { Step, Terrain } from './types';

export const { alsStrideCv, controlStrideCv } = physionet;

const zStrides = physionet.als.flatMap(series => {
  const mean = series.reduce((a, b) => a + b, 0) / series.length;
  const sd = Math.sqrt(series.reduce((a, b) => a + (b - mean) ** 2, 0) / series.length);
  return series.map(ms => (ms - mean) / sd);
});
let cursor = -1;

export function syntheticStep(time: Date, terrain: Terrain, decline = 1, random = Math.random): Step {
  const hour = time.getHours();
  const fatigue = hour >= 18 ? 5 : hour >= 12 ? 2.5 : 0;
  const noise = (random() - 0.5) * 3;
  if (cursor < 0) cursor = Math.floor(random() * zStrides.length);
  const z = zStrides[cursor++ % zStrides.length];
  const strideCv = controlStrideCv + (alsStrideCv - controlStrideCv) * (decline + fatigue / 5);
  return {
    time: time.toISOString(), terrain,
    minClearanceMm: Math.max(2, 26 - decline * 6 - fatigue - (terrain === 'level' ? 0 : 2) + noise),
    peakDorsiDeg: 13 - decline * 4 - fatigue * 0.45 + noise * 0.3,
    strideMs: Math.round((1040 + decline * 60) * (1 + z * strideCv)),
    assistPct: Math.round(clamp(25 + decline * 25 + fatigue * 3 + (terrain === 'level' ? 0 : 8), 0, 100)),
  };
}

