const WINDOW_MS = 10_000;
const PLAYBACK_DELAY_MS = 300;
const Y_MIN = -25;
const Y_MAX = 20;
const Y_TICKS = [-20, -10, 0, 10, 20];
const GUTTER = 30;

function Trace() {
  const store = useLiveStore();
  const hasData = useLive((s) => s.samples.length > 0);
  const canvas = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const el = canvas.current;
    if (!el) return;
    const ctx = el.getContext("2d")!;
    let colors = { accent: "", line: "", muted: "" };
    const readColors = () => {
      const css = getComputedStyle(el);
      colors = { accent: css.getPropertyValue("--accent"), line: css.getPropertyValue("--line"), muted: css.getPropertyValue("--muted") };
    };
    const resize = () => {
      const dpr = devicePixelRatio || 1;
      el.width = el.clientWidth * dpr;
      el.height = el.clientHeight * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    readColors();
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(el);
    const scheme = matchMedia("(prefers-color-scheme: dark)");
    scheme.addEventListener("change", readColors);

    let frame = 0;
    const draw = () => {
      frame = requestAnimationFrame(draw);
      const { samples, sampleArrivedAt } = store.state;
      const w = el.clientWidth;
      const h = el.clientHeight;
      const plot = w - GUTTER;
      const y = (deg: number) => 6 + ((Y_MAX - deg) / (Y_MAX - Y_MIN)) * (h - 12);
      ctx.clearRect(0, 0, w, h);
      ctx.font = "11px var(--font-inter), system-ui, sans-serif";
      ctx.textBaseline = "middle";
      ctx.lineWidth = 1;
      for (const t of Y_TICKS) {
        ctx.fillStyle = colors.muted;
        ctx.fillText(`${t}°`, 0, y(t));
        if (t === 0) {
          ctx.strokeStyle = colors.line;
          ctx.beginPath();
          ctx.moveTo(GUTTER, y(0));
          ctx.lineTo(w, y(0));
          ctx.stroke();
        }
      }
      if (!samples.length) return;
      // render slightly behind the newest sample so bursty WebSocket batches scroll at a constant rate
      const last = Date.parse(samples[samples.length - 1].time);
      const end = last + Math.min(performance.now() - sampleArrivedAt, 2_000) - PLAYBACK_DELAY_MS;
      const x = (t: number) => GUTTER + ((t - (end - WINDOW_MS)) / WINDOW_MS) * plot;
      ctx.save();
      ctx.beginPath();
      ctx.rect(GUTTER, 0, plot, h);
      ctx.clip();
      ctx.strokeStyle = colors.accent;
      ctx.lineWidth = 2;
      ctx.lineJoin = "round";
      ctx.beginPath();
      samples.forEach((s, i) => {
        const px = x(Date.parse(s.time));
        const py = y(s.ankleDeg);
        if (i) ctx.lineTo(px, py);
        else ctx.moveTo(px, py);
      });
      ctx.stroke();
      ctx.restore();
    };
    draw();
    return () => {
      cancelAnimationFrame(frame);
      ro.disconnect();
      scheme.removeEventListener("change", readColors);
    };
  }, [store, hasData]);

  if (!hasData) return <Empty className="h-44">Waiting for live data from the brace.</Empty>;
  return (
    <div>
      <canvas ref={canvas} className="block h-40 w-full" aria-label="Live ankle angle trace" role="img" />
      <div className="mt-1 flex justify-between pl-[30px] text-[11px] text-muted">
        <span>-10 s</span>
        <span>-5 s</span>
        <span>now</span>
      </div>
    </div>
  );
}

