async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const measure = async ms => {
    const tasks = []; const po = new PerformanceObserver(l => l.getEntries().forEach(e => tasks.push(e.duration))); po.observe({ type: 'longtask' });
    let frames = 0, worst = 0, last = performance.now(), run = true;
    const tick = t => { frames++; worst = Math.max(worst, t - last); last = t; if (run) requestAnimationFrame(tick); }; requestAnimationFrame(tick);
    await sleep(ms); run = false; po.disconnect();
    return { fps: Math.round(frames / (ms / 1000)), worstFrameMs: Math.round(worst), longTasks: tasks.length, blockedMs: Math.round(tasks.reduce((a, b) => a + b, 0)) };
  };
  const btn = name => [...document.querySelectorAll('button')].find(b => b.textContent.trim() === name);
  const clickLatency = async name => {
    const t0 = performance.now(); btn(name).click();
    await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
    return Math.round(performance.now() - t0);
  };
  await sleep(3000);
  const out = {};
  out.toPhysicianMs = await clickLatency('Physician');
  await sleep(1500);
  out.physicianIdle = await measure(4000);
  out.chipMs = await clickLatency('Assist change');
  out.chipAllMs = await clickLatency('All');
  out.toFamilyMs = await clickLatency('Family');
  await sleep(800);
  out.familyIdle = await measure(3000);
  out.backToPhysicianMs = await clickLatency('Physician');
  out.canvas = !!document.querySelector('canvas');
  return out;
}

